<template>
  <main class="content">
    <section v-if="!isAdmin" class="hero-banner">
      <div class="hero-copy"><span class="hero-kicker">SANTANDER · COLOMBIA</span><h1>Descubre tu próxima aventura en San Gil</h1><p>Ríos, montañas y caminos que se quedan contigo mucho después del viaje.</p><button class="story-cta" @click="router.push({ name: 'sobre-nosotros' })">Conoce nuestra historia y guías <svg viewBox="0 0 24 24"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></button></div>
      <div class="hero-stats"><div><strong>+15.000</strong><span>Aventureros felices</span></div><i></i><div><strong>30</strong><span>Experiencias únicas</span></div><i></i><div><strong>100%</strong><span>Guías certificados</span></div></div>
      <span class="hero-coordinate">6°33′N · 73°08′W</span>
    </section>
    <header v-if="isAdmin" class="page-header">
      <div><span class="kicker">{{ isAdmin ? 'OPERACIÓN · SAN GIL' : 'SAN GIL · SANTANDER' }}</span><h1>{{ isAdmin ? 'Gestión de servicios' : 'Descubre tu próxima aventura' }}</h1><p>{{ isAdmin ? 'Administra experiencias, precios y disponibilidad.' : 'Explora ríos, montañas y caminos extraordinarios alrededor de San Gil.' }}</p></div>
      <button v-if="isAdmin" class="btn-primary" @click="openCreateModal">＋ Nuevo servicio</button>
    </header>

    <div v-if="!isAdmin" class="catalog-tools">
      <label class="search-box"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg><input v-model="searchQuery" type="search" placeholder="Buscar rafting, parapente, cuevas…"></label>
      <div class="category-chips" aria-label="Filtrar por categoría"><button v-for="categoryName in categories" :key="categoryName" class="category-chip" :class="{ 'category-chip--active': activeCategory === categoryName }" @click="activeCategory = categoryName">{{ categoryName }}</button></div>
    </div>

    <p v-if="loading" class="loading-text">Preparando tus experiencias…</p>
    <section v-else-if="!isAdmin" class="experience-grid">
      <article v-for="(service, index) in filteredServices" :key="service._id || service.id" class="experience-card" :class="{ 'is-flipped': flippedService === serviceKey(service) }">
        <div class="card-inner">
          <div class="card-face card-face--front">
            <div class="card-image"><img :src="service.imageUrl || imageFor(service, index)" :alt="service.nombre" @error="useFallback($event, index)"><span class="image-label">{{ categoryOf(service) }}</span><span class="image-duration">{{ service.duracion }} min</span></div>
            <div class="card-body"><div class="card-meta"><span>SAN GIL, SANTANDER</span><span>EXPERIENCIA LOCAL</span></div><h2>{{ service.nombre }}</h2><p>{{ service.descripcion || 'Una experiencia local diseñada para conectar con la naturaleza.' }}</p><div class="card-footer"><strong>{{ currency(service.precio) }}</strong><button class="reserve-button" @click.stop="book(service)">Reservar <span>→</span></button><button class="details-button" :aria-expanded="flippedService === serviceKey(service)" @click.stop="toggleDetails(service)">Detalles</button></div></div>
          </div>
          <div class="card-face card-face--back">
            <div class="detail-card-heading"><span class="detail-icon"><svg viewBox="0 0 24 24"><path d="M12 3 3 8l9 5 9-5-9-5zm-9 9 9 5 9-5M3 16l9 5 9-5"/></svg></span><div><span>GUÍA DE EXPERIENCIA</span><h2>Antes de reservar</h2></div></div>
            <div class="difficulty-pill">{{ adventureDetails(service).dificultad }}</div>
            <div class="details-list"><div class="detail-item"><span>Requisitos</span><strong>{{ adventureDetails(service).requisitos }}</strong></div><div class="detail-item"><span>Equipo incluido</span><strong>{{ adventureDetails(service).equipo }}</strong></div><div class="detail-item"><span>Edad y restricciones</span><strong>{{ adventureDetails(service).edad }}</strong></div><div class="detail-item"><span>Punto de encuentro</span><strong>{{ adventureDetails(service).encuentro }}</strong></div></div>
            <div class="details-actions"><button class="details-button" @click.stop="toggleDetails(service)">Volver</button><button class="reserve-button" @click.stop="book(service)">Reservar ahora <span>→</span></button></div>
          </div>
        </div>
      </article>
      <div v-if="!filteredServices.length" class="empty-state">No encontramos experiencias para esa búsqueda. Prueba con otra palabra.</div>
    </section>

    <section v-else class="admin-panel"><table class="services-table"><thead><tr><th>Experiencia</th><th>Precio</th><th>Duración</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>
      <tr v-if="services.length === 0"><td colspan="5" class="empty-cell">Aún no hay servicios.</td></tr>
      <tr v-for="service in services" :key="service._id || service.id"><td><div class="service-cell"><img :src="service.imageUrl || imageFor(service, 0)" alt=""><div><strong>{{ service.nombre }}</strong><small>{{ service.descripcion }}</small></div></div></td><td>{{ currency(service.precio) }}</td><td>{{ service.duracion }} min</td><td><span class="badge" :class="service.estado === 'activo' ? 'badge--success' : 'badge--muted'">{{ service.estado }}</span></td><td><div class="action-buttons"><button class="btn-icon btn-icon--edit" @click="openEditModal(service)">Editar</button><button v-if="service.estado === 'activo'" class="btn-icon btn-icon--danger" @click="openDeleteModal(service)">Desactivar</button><button v-else class="btn-icon btn-icon--activate" @click="reactivate(service)">Activar</button></div></td></tr>
    </tbody></table></section>

    <ServicioModal :show="showModal" :service-data="selectedService" :submitting="submitting" :form-error="modalError" @close="showModal = false" @save="handleSaveService" />
    <ConfirmModal :show="showDeleteModal" title="¿Desactivar experiencia?" :message="`¿Confirmas desactivar '${selectedService?.nombre}'? Sus reservas anteriores seguirán en el historial.`" :loading="deleting" @close="showDeleteModal = false" @confirm="handleConfirmDelete" />
  </main>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import api from '../services/api'
import ServicioModal from '../components/ServicioModal.vue'
import ConfirmModal from '../components/ConfirmModal.vue'
import { formatCOP } from '../utils/currency'

const router = useRouter()
const isAdmin = JSON.parse(localStorage.getItem('user') || '{}').rol === 'admin'
const services = ref([]), loading = ref(true), searchQuery = ref(''), activeCategory = ref('Todos')
const flippedService = ref(null)
const categories = ['Todos', 'R\u00edos y Agua', 'Alturas y Aire', 'Caminatas y Cuevas']
const showModal = ref(false), showDeleteModal = ref(false), selectedService = ref(null)
const submitting = ref(false), deleting = ref(false), modalError = ref('')
const photos = [
  'https://images.unsplash.com/photo-1530866495561-507c9faab2ed?auto=format&fit=crop&w=1200&q=85',
  'https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=1200&q=85',
  'https://images.unsplash.com/photo-1511497584788-876760111969?auto=format&fit=crop&w=1200&q=85'
]
const filteredServices = computed(() => services.value.filter(service => {
  const matchesSearch = `${service.nombre} ${service.descripcion || ''}`.toLocaleLowerCase().includes(searchQuery.value.toLocaleLowerCase().trim())
  return matchesSearch && (activeCategory.value === 'Todos' || categoryOf(service) === activeCategory.value)
}))
async function fetchServices() { loading.value = true; try { services.value = (await api.get('/servicios')).data } catch (error) { console.error('Error al cargar experiencias:', error) } finally { loading.value = false } }
onMounted(fetchServices)
function imageFor(service, index) { const name = service.nombre.toLowerCase(); return photos[name.includes('parapente') ? 1 : name.includes('cueva') || name.includes('espele') ? 2 : index % photos.length] }
function useFallback(event, index) { event.target.src = photos[(index + 1) % photos.length] }
function normalizeText(value) { return String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase() }
function categoryOf(service) {
  const category = normalizeText(service.categoria)
  if (category.includes('rio') || category.includes('agua')) return categories[1]
  if (category.includes('altura') || category.includes('aire')) return categories[2]
  if (category.includes('caminata') || category.includes('cueva')) return categories[3]
  const name = normalizeText(service.nombre)
  return /rafting|rio|canotaje|torrentismo|cascada|kayak|tubing/.test(name) ? categories[1] : /parapente|bungee|cable|tirolina|escalada|puenting/.test(name) ? categories[2] : categories[3]
}
function adventureDetails(service) {
  const category = categoryOf(service)
  const name = normalizeText(service.nombre)
  const isFamily = /familiar|principiante|canotaje/.test(name)
  let defaults
  if (category === categories[1]) defaults = { dificultad: isFamily ? 'Facil - familiar' : /suarez|profesional|extremo/.test(name) ? 'Alta - avanzada' : 'Media - activa', requisitos: 'Saber nadar y seguir instrucciones del guia', equipo: 'Casco, chaleco, remo y equipo tecnico', edad: isFamily ? 'Desde 8 anos' : 'Desde 14 anos', encuentro: /juan curi|pinchote/.test(name) ? 'Cascadas - punto acordado' : 'Malecon del Rio Fonce' }
  else if (category === categories[2]) defaults = { dificultad: /bungee|puenting|escalada/.test(name) ? 'Alta - adrenalina' : 'Media - guiada', requisitos: 'Condicion fisica basica; sin restricciones medicas relevantes', equipo: 'Arnes, casco y sistema de seguridad certificado', edad: 'Desde 14 anos; autorizacion de acudiente si aplica', encuentro: /chicamocha/.test(name) ? 'Mirador del Canon del Chicamocha' : 'Base de aventura - San Gil' }
  else defaults = { dificultad: /mtb|cuatrimoto|avanzada/.test(name) ? 'Media - activa' : 'Facil a media', requisitos: 'Calzado cerrado y disposicion para caminar', equipo: /caving|cueva|espele/.test(name) ? 'Casco, iluminacion y proteccion' : 'Guia local y kit de hidratacion', edad: /cueva|caving|espele/.test(name) ? 'Desde 12 anos' : 'Desde 8 anos', encuentro: /barichara|guane/.test(name) ? 'Parque principal de Barichara' : 'Parque principal - San Gil' }
  return { ...defaults, requisitos: service.requisitosFisicos || defaults.requisitos, edad: service.restriccionesEdad || defaults.edad, equipo: service.incluye || defaults.equipo }
}
function currency(value) { return formatCOP(value) }
function serviceKey(service) { return String(service._id || service.id) }
function toggleDetails(service) { const key = serviceKey(service); flippedService.value = flippedService.value === key ? null : key }
function book() { router.push({ name: 'reservas', query: { nueva: '1' } }) }
function openCreateModal() { selectedService.value = null; modalError.value = ''; showModal.value = true }
function openEditModal(service) { selectedService.value = service; modalError.value = ''; showModal.value = true }
function openDeleteModal(service) { selectedService.value = service; showDeleteModal.value = true }
async function handleSaveService(payload) { submitting.value = true; modalError.value = ''; try { if (payload.isEditing) await api.put(`/servicios/${payload.id || payload._id}`, payload); else await api.post('/servicios', payload); showModal.value = false; await fetchServices() } catch (error) { modalError.value = error.response?.data?.mensaje || 'No se pudo guardar el servicio.' } finally { submitting.value = false } }
async function handleConfirmDelete() { if (!selectedService.value) return; deleting.value = true; try { await api.delete(`/servicios/${selectedService.value._id || selectedService.value.id}`); showDeleteModal.value = false; await fetchServices() } catch (error) { modalError.value = error.response?.data?.mensaje || 'No se pudo desactivar la experiencia.' } finally { deleting.value = false } }
async function reactivate(service) { try { await api.put(`/servicios/${service._id || service.id}`, { estado: 'activo' }); await fetchServices() } catch (error) { console.error(error) } }
</script>

